/// @brief Enumeration for the Wi-Fi error type.
/// @since_tizen 3.0
abstract class wifi_manager_error_e {
  /// Successful
  static const int WIFI_MANAGER_ERROR_NONE = 0;

  /// Invalid parameter
  static const int WIFI_MANAGER_ERROR_INVALID_PARAMETER = -22;

  /// Out of memory error
  static const int WIFI_MANAGER_ERROR_OUT_OF_MEMORY = -12;

  /// Invalid operation
  static const int WIFI_MANAGER_ERROR_INVALID_OPERATION = -38;

  /// Address family not supported
